 DO $$ DECLARE     v_admin_id UUID := 'd0680fc1-5fa0-4a54-b9bd-6918f88de63a';     v_cat_guides UUID := '448d06b4-5a1d-4c90-b37e-019f22ec9064';     v_cat_lore UUID := 'ceb24c42-7d36-483c-880b-e0e08d5c4d99';     v_cat_colonization UUID := '117fddde-9c52-4741-b00d-edb2788e4e42';     v_cat_ring UUID := '46bc3a47-b334-4f45-b449-bbd17ba4e014';     v_article_id UUID; BEGIN     -- ============================================================     -- КАТЕГОРИЯ: ГАЙДЫ (3 статьи)     -- ============================================================     INSERT INTO public.wiki_articles (title, slug, content, category_id, author_id, last_editor_id, status, is_featured, view_count, version, created_at, updated_at)     VALUES (         'Первые шаги новичка',         'pervye-shagi-novichka',         $c$# Первые шаги новичка$nl$$nl$**Тип:** Гайд$nl$**Сложность:** Начальный$nl$**Время чтения:** 15 минут$nl$$nl$## Описание$nl$$nl$Только что купили Elite Dangerous и не знаете, с чего начать? Этот гайд проведёт вас от первого запуска до осознанного выбора профессии. Не торопитесь — игра вознаградит любопытство.$nl$$nl$## Этап 1: Прохождение обучения$nl$$nl$Не пропускайте обучение. Оно научит:$nl$- Базовому управлению (взлёт, посадка, FSD)$nl$- Суперкруизу и выходу из него$nl$- Стыковке вручную и через Docking Computer$nl$- Базовому бою и сканированию$nl$$nl$## Этап 2: Первые кредиты (Sidewinder)$nl$$nl$| Способ | Доход | Сложность |$nl$|--------|-------|-----------|$nl$| Миссии «Доставка данных» | 10–50 тыс. | Низкая |$nl$| Поиск обломков (RES) | 20–100 тыс. | Средняя |$nl$| Базовая торговля | 5–20 тыс. | Низкая |$nl$$nl$Рекомендация: выполните 3–5 миссий на доставку данных, чтобы накопить на Cobra Mk III (~350 тыс.)$nl$$nl$## Этап 3: Первый апгрейд корабля$nl$$nl$**Цель:** Cobra Mk III$nl$- Универсальность: торговля, бой, исследования$nl$- 4 внутренних слота$nl$- Достаточно щитов и скорости$nl$$nl$Обязательные модули для покупки:$nl$1. **D-rated FSD** — максимальная дальность прыжка$nl$2. **Fuel Scoop** — бесплатное топливо от звёзд$nl$3. **Detailed Surface Scanner** — заработок на исследованиях$nl$$nl$## Этап 4: Выбор пути$nl$$nl$После Cobra Mk III выберите специализацию:$nl$$nl$| Профессия | Следующий корабль | Что делать |$nl$|-----------|-------------------|------------|$nl$| Торговля | Type-6 Transporter | Loop routes, rare goods |$nl$| Бой | Vulture | RES, Combat Zones |$nl$| Исследования | Diamondback Explorer | Дальние миры, продажа данных |$nl$| Многоцелевой | Python | Всё понемногу |$nl$$nl$## Советы$nl$$nl$- **Не летайте без страховки (Rebuy)** — всегда держите 5–10% стоимости корабля$nl$- **Используйте Inara.cz и EDDB** — внеигровые инструменты экономят часы$nl$- **Присоединяйтесь к Squadron** — сообщество поможет и ответит на вопросы$nl$- **Откройте Felicity Farseer** — первый инженер, G5 FSD — must have$nl$- **Не бойтесь Open** — PvP-гриферы редки, а помощь других игроков бесценна$nl$$nl$## Оценка$nl$$nl$Первые 10 часов в Elite Dangerous — самые важные. Не гонитесь за кредитами, изучайте механики. Хорошо настроенный Cobra Mk III принесёт больше удовольствия, чем stock Anaconda.$c$,         v_cat_guides, v_admin_id, v_admin_id, 'published', true, 0, 1, NOW(), NOW()     ) RETURNING id INTO v_article_id;     INSERT INTO public.wiki_revisions (article_id, content, editor_id, revision_number, change_summary, created_at)     VALUES (v_article_id, (SELECT content FROM public.wiki_articles WHERE id = v_article_id), v_admin_id, 1, 'Initial seed', NOW());     INSERT INTO public.wiki_articles (title, slug, content, category_id, author_id, last_editor_id, status, is_featured, view_count, version, created_at, updated_at)     VALUES (         'Быстрый заработок кредитов',         'bystryj-zarabotok-kreditov',         $c$# Быстрый заработок кредитов$nl$$nl$**Тип:** Гайд$nl$**Сложность:** Любая$nl$**Актуальность:** 2026$nl$$nl$## Описание$nl$$nl$Elite Dangerous предлагает множество способов заработка. Этот гайд описывает самые эффективные методы на разных этапах карьеры — от стартового Sidewinder до флота Fleet Carrier.$nl$$nl$## Начальный этап (0–5 млн CR)$nl$$nl$| Метод | Доход/час | Требования |$nl$|-------|-----------|------------|$nl$| Миссии доставки данных | 0.5–1 млн | Sidewinder, любая станция |$nl$| Road to Riches | 1–3 млн | Cobra Mk III + DSS + Fuel Scoop |$nl$| Низкоуровневый RES | 1–2 млн | Любой боевой корабль, система с RES |$nl$$nl$**Road to Riches** — сканируйте дорогие планеты (Earth-like, Water worlds) в пределах 5000 св. лет от Bubble. Маршруты есть на [EDTools](https://edtools.cc/).$nl$$nl$## Средний этап (5–500 млн CR)$nl$$nl$| Метод | Доход/час | Требования |$nl$|-------|-----------|------------|$nl$| Void Opals / LTD mining | 50–200 млн | Корабль с трюмом 100+ т, seismic charges |$nl$| Passenger missions (Robigo) | 20–50 млн | Python, 3A Business cabins |$nl$| Stackable massacre missions | 30–100 млн | Корабль G3+, allied фракция |$nl$$nl$**Robigo Mines** — станция в системе Robigo. Берите пассажиров в Sirius Atmospherics, летите в Sothis. 10-минутный рейс, 10–20 млн прибыли.$nl$$nl$## Продвинутый этап (500 млн+)$nl$$nl$| Метод | Доход/час | Требования |$nl$|-------|-----------|------------|$nl$| Platinum laser mining | 100–300 млн | Type-9 / Cutter, mapped hotspot |$nl$| Thargoid interceptor hunting | 100–500 млн | AX-krait, опыт |$nl$| Colonization logistics | 50–200 млн | Fleet Carrier, Type-11 |$nl$$nl$## Советы$nl$$nl$- Не гонитесь только за кредитами — инженеры важнее$nl$- Fleet Carrier стоит 5 млрд + 500 млн/неделю upkeep — считайте заранее$nl$- Используйте [Mineraltools](https://mineraltools.com) для поиска актуальных hotspot'ов$nl$- Community Goals часто дают десятки миллионов за простые действия$nl$$nl$## Оценка$nl$$nl$Лучший заработок — тот, который вам не надоеден. Mining приносит больше всего, но быстро утомляет. Passenger Robigo — золотая середина: стабильный, предсказуемый, не требует постоянного внимания.$c$,         v_cat_guides, v_admin_id, v_admin_id, 'published', false, 0, 1, NOW(), NOW()     ) RETURNING id INTO v_article_id;     INSERT INTO public.wiki_revisions (article_id, content, editor_id, revision_number, change_summary, created_at)     VALUES (v_article_id, (SELECT content FROM public.wiki_articles WHERE id = v_article_id), v_admin_id, 1, 'Initial seed', NOW());     INSERT INTO public.wiki_articles (title, slug, content, category_id, author_id, last_editor_id, status, is_featured, view_count, version, created_at, updated_at)     VALUES (         'Гайд по открытию инженеров',         'gayd-po-otkrytiyu-inzhenerov',         $c$# Гайд по открытию инженеров$nl$$nl$**Тип:** Гайд$nl$**Сложность:** Средняя$nl$**Время:** 10–30 часов$nl$$nl$## Описание$nl$$nl$Инженеры — ключевая прогрессия в Elite Dangerous. G5-модификации превращают стоковый корабль в машину, способную на всё. Этот гайд описывает оптимальный порядок открытия и требования для каждого инженера.$nl$$nl$## Порядок открытия (рекомендуемый)$nl$$nl$| # | Инженер | Зачем открывать | Сложность |$nl$|---|---------|-----------------|-----------|$nl$| 1 | Felicity Farseer | G5 FSD, G3 Thrusters | Очень низкая |$nl$| 2 | Tod McQuinn | G5 Multi-cannons, G3 Railguns | Низкая |$nl$| 3 | The Dweller | G5 Power Distributor | Низкая |$nl$| 4 | Elvira Martuuk | G5 FSD (альтернатива) | Низкая |$nl$| 5 | Liz Ryder | G5 Missiles, G3 Torpedoes | Низкая |$nl$| 6 | Selene Jean | G5 Hull | Средняя |$nl$| 7 | Didi Vatermann | G5 Shield Boosters | Средняя |$nl$| 8 | Lei Cheung | G5 Shields | Средняя |$nl$| 9 | Marco Qwent | G4 Power Plant, открывает Palin | Средняя |$nl$| 10 | Professor Palin | G5 Thrusters, G3 AFMU | Высокая |$nl$$nl$## Как начать$nl$$nl$1. **Felicity Farseer** — требует звание Scout в исследованиях. Сделайте Road to Riches, продайте данные в Farseer Inc (Deciat)$nl$2. **Meta-Alloys** — купите у Darnielle's Progress (Maia) или соберите с Thargoid Barnacle$nl$3. **Marco Qwent** — требует приглашение от Elvira Martuuk и 25 единиц Modular Terminals (миссии Sirius Corp)$nl$4. **Professor Palin** — требует 5000 св. лет от стартовой системы + приглашение от Marco Qwent$nl$$nl$## Быстрые материалы для старта$nl$$nl$| Инженер | Что принести | Где взять |$nl$|---------|--------------|-----------|$nl$| Felicity | 1 Meta-Alloy | Maia — Darnielle's Progress |$nl$| Tod McQuinn | 15 Fragment Cannons убийств | Any RES |$nl$| The Dweller | 5 единиц Black Market | Продайте контрабанду |$nl$| Liz Ryder | 200 единиц Landmines | Eurybia — Kammerman's Port |$nl$$nl$## Советы$nl$$nl$- Не пытайтесь открыть всех сразу — это выгорание$nl$- Сначала поднимите репутацию (G1→G3 модули), потом фармите G5 материалы$nl$- Используйте [Inara](https://inara.cz) для отслеживания требований$nl$- pinned blueprint — закреплённый чертёж, позволяет крафтить удалённо$nl$- Experimental effects доступны только на базе инженера$nl$$nl$## Оценка$nl$$nl$Инженеры — must have для любой серьёзной деятельности. Даже G3 FSD от Felicity удвоит вашу дальность. Потратьте 2–3 вечера на открытие первой пятёрки — это окупится сторицей.$c$,         v_cat_guides, v_admin_id, v_admin_id, 'published', false, 0, 1, NOW(), NOW()     ) RETURNING id INTO v_article_id;     INSERT INTO public.wiki_revisions (article_id, content, editor_id, revision_number, change_summary, created_at)     VALUES (v_article_id, (SELECT content FROM public.wiki_articles WHERE id = v_article_id), v_admin_id, 1, 'Initial seed', NOW()); END $$;